insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI 3D Product Animation', 'ai-3d-product-animation', 'A hands-on 3d product animation production course built on Blender: six guided lessons, real deliverables, and a certified capstone project.', 'A hands-on 3d product animation production course built on Blender: six guided lessons, real deliverables, and a certified capstone project.

This is a hands-on, self-paced course in the Video, Audio & Media track, built around the verified flagship tutorial "Full 3.5 Hour Product Animation Masterclass [Blender 4.3]" by The Blenderender. Across 6 guided lessons (about 5 hours of structured work), you''ll follow the full video while working in Blender — every lesson pairs the walkthrough with notes, a practical activity and a reflection check, so you''re building from day one rather than just watching.

Who it''s for: digital professionals seeking practical AI capabilities; entrepreneurs and freelancers offering client services; teams looking to streamline operational workflows.

The course finishes with a final assessment and a practical capstone — Complete Commercial Capstone Portfolio: AI 3D Product Animation. A high-growth commercial client requires a complete, production-ready deliverable demonstrating comprehensive mastery of AI 3D Product Animation. Submit it, pass the assessment, and you''ll earn a signed, verifiable Najeeb Academy certificate you can share with employers and clients.

Level: Intermediate. Basic computer literacy and familiarity with digital productivity tools. Lifetime access, learn at your own pace, and all future updates to the course are included in the one-time ₦35,000 fee.', 'video-media', 35000, '5 hours', '/images/courses/ai-3d-product-animation.jpg', true, 'Intermediate', false, array['Blender']::text[], 'A high-growth commercial client requires a complete, production-ready deliverable demonstrating comprehensive mastery of AI 3D Product Animation.');
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-3d-product-animation'), 'Introduction & Environment Setup for AI 3D Product Animation', 'introduction-and-environment-setup-for-ai-3d-product-animation', '<p>Lesson <strong>1 of 6</strong> in <strong>AI 3D Product Animation</strong>: Introduction &amp; Environment Setup for AI 3D Product Animation.</p><p><strong>Watch:</strong> the section of the course video above that covers this milestone. Work along in Blender as you watch — pause freely and repeat steps until each one feels natural.</p><p>Comprehensive exploration of introduction &amp; environment setup for ai 3d product animation within the verified tutorial framework.</p><h3>Practical activity</h3><p>Complete the follow-along practical exercise for introduction &amp; environment setup for ai 3d product animation in your workspace.</p><h3>Reflection check</h3><p>What key operational challenge in introduction &amp; environment setup for ai 3d product animation requires human judgment over automated output?</p><h3>Next up</h3><p>When your activity output looks solid, mark this lesson complete and continue to <em>Core Frameworks, Prompting &amp; Tool Workflows</em> — your progress is saved to your dashboard automatically.</p>', 'https://www.youtube-nocookie.com/embed/z4PKYW6DnKw', 1);